#!/usr/bin/env bash
# SPDX-License-Identifier: MIT OR Apache-2.0
# Copyright (c) 2026 TPT Solutions
#
# Generates each project template with `tpt-shell new <template> <dir>`, then checks the result
# with `tpt-shell manifest check` and `tpt-shell build` (spec §16 M11: every template is generated
# and built in CI, then smoke-tested). Then builds every example under examples/.
#
# A template is a directory under templates/. The CLI generates a template by its name, so the
# directory name must match a `tpt-shell new` subcommand. The web-only starters (vanilla and
# typescript) are generated by the CLI; the Rust templates are copied as they are and their path
# dependencies are pointed at this checkout. Running the generated app needs a desktop and is not
# done here; it belongs to the M11 gate.
#
# usage: tools/template-build.sh [path-to-tpt-shell-binary]

set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
templates_dir="$root/templates"
examples_dir="$root/examples"

names=()
if [ -d "$templates_dir" ]; then
  for dir in "$templates_dir"/*/; do
    [ -d "$dir" ] || continue
    # templates/rust holds the files that `tpt-shell new rust` renders (*.tmpl); it is not a project.
    [ "$(basename "$dir")" = "rust" ] && continue
    names+=("$(basename "$dir")")
  done
fi

if [ "${#names[@]}" -eq 0 ]; then
  echo "no templates: templates/ has no template directories"
  exit 1
fi

cli="${1:-}"
if [ -z "$cli" ]; then
  cargo build --quiet --manifest-path "$root/Cargo.toml" -p tpt-shell-cli
  cli="$root/target/debug/tpt-shell"
  [ -x "$cli" ] || cli="$cli.exe"
fi

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

status=0
for name in "${names[@]}"; do
  dest="$work/$name"
  # `tpt-shell new` only scaffolds the two starter apps. Every other template is a checked-in
  # Rust project, so it is copied as it is.
  case "$name" in
    vanilla | typescript)
      echo "== generate $name"
      if ! "$cli" new "$name" "$dest"; then
        echo "template $name did not generate" >&2
        status=1
        continue
      fi
      ;;
    *)
      echo "== copy $name"
      # Copy without build output, so the copy never carries a previous build.
      mkdir -p "$dest"
      (cd "$templates_dir/$name" && tar --exclude=./target -cf - .) | (cd "$dest" && tar -xf -)
      # The templates point at the crates with a path relative to templates/<name>. The copy
      # lives elsewhere, so the path is rewritten to this checkout.
      # `pwd -W` gives the Windows form of the path under Git Bash; elsewhere it is plain `pwd`.
      crates="$(cd "$root/crates" && pwd -W 2>/dev/null || pwd)"
      sed -i "s#path = \"\.\./\.\./crates/#path = \"$crates/#" "$dest/Cargo.toml"
      ;;
  esac
  echo "== check $name"
  if [ -f "$dest/tpt-shell.toml" ] && ! "$cli" manifest check "$dest/tpt-shell.toml"; then
    echo "template $name has a manifest that does not check" >&2
    status=1
    continue
  fi
  # The starter apps are web projects with no Cargo.toml; `tpt-shell build` only builds Rust
  # projects, so they are checked here and built by their own toolchain.
  if [ ! -f "$dest/Cargo.toml" ]; then
    echo "== skip build $name (not a Rust project)"
    continue
  fi
  # `tpt-shell build` passes --locked, and the templates ship without a lock file, so the copy
  # gets one resolved here first.
  if [ ! -f "$dest/Cargo.lock" ]; then
    cargo generate-lockfile --manifest-path "$dest/Cargo.toml" --quiet
  fi
  echo "== build $name"
  if ! "$cli" build "$dest"; then
    echo "template $name did not build" >&2
    status=1
  fi
done

# Examples are standalone Rust projects in the repository (excluded from the workspace, so each
# one is built on its own, against the crates by path).
for dir in "$examples_dir"/*/; do
  [ -f "$dir/Cargo.toml" ] || continue
  name="$(basename "$dir")"
  echo "== build example $name"
  if ! cargo build --quiet --manifest-path "$dir/Cargo.toml"; then
    echo "example $name did not build" >&2
    status=1
  fi
done
exit "$status"
